// Small current-only metadata query; no row scans, RPCs, DDL or intervention.
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { createHash } from "node:crypto";
import { own, credential } from "./governance-approval-hosted-20261002.release-20261004.mjs";
const proposal=JSON.parse(await readFile(path.join(own,"GOVERNANCE-BUSINESS-CONFLICT-PROPOSAL-20261004-v2.json"),"utf8"));
const token=await credential("SUPABASE_ACCESS_TOKEN");const sha=x=>createHash("sha256").update(x).digest("hex");const quote=x=>`'${x.replaceAll("'","''")}'`;
const results=await Promise.all(["PROD","DEV"].map(async environment=>{
 const packet=proposal.environments[environment];const captured=JSON.parse(await readFile(packet.catalog_file,"utf8")).result[0].metadata.functions;
 const ports=packet.changed.map(row=>{const f=captured.find(x=>`${x.schema}.${x.name}`===row.function.split('(')[0]);let after=f.body.replace(/ERRCODE\s*=\s*'40001'/gu,"ERRCODE='PT409'");if(row.snapshot_catch_changed)after=after.replace("EXCEPTION WHEN SQLSTATE '40001'","EXCEPTION WHEN SQLSTATE 'PT409'");return `SELECT ${quote(row.function)} AS signature,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS current_body_sha256,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=${quote(row.before_body_sha256)} AS preimage_matches,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=${quote(sha(after))} AS pt409_postimage_matches,p.proowner=${quote(f.owner)}::regrole AND p.prosecdef AS authority_matches,p.proconfig IS NOT DISTINCT FROM ${f.config?`ARRAY[${f.config.map(quote).join(',')}]::text[]`:'NULL::text[]'} AS config_matches,p.proacl IS NOT DISTINCT FROM ${f.acl?`${quote('{'+f.acl.join(',')+'}')}::aclitem[]`:'NULL::aclitem[]'} AS acl_matches FROM pg_proc p WHERE p.oid=${quote(row.function)}::regprocedure`;});
 const backend=environment==="PROD"?`(SELECT jsonb_agg(jsonb_build_object('pid',pid,'backend_start',backend_start,'user',usename,'application',application_name,'state',state,'query_start',query_start,'xact_start',xact_start,'wait_type',wait_event_type,'wait_event',wait_event,'blocking_pids',pg_blocking_pids(pid),'query_sha256',encode(sha256(convert_to(coalesce(query,''),'UTF8')),'hex'),'query_kind',CASE WHEN query ILIKE '%withdraw_governance_membership_request%' THEN 'governance_membership_withdraw' ELSE 'OTHER-NOT-ATTRIBUTED' END)) FROM pg_stat_activity WHERE pid=1165594)`:'NULL::jsonb';
 const query=`SELECT jsonb_build_object('captured_at',clock_timestamp(),'engine',current_setting('server_version_num')::int,'ledger',(SELECT count(*)::int FROM supabase_migrations.schema_migrations),'latest',(SELECT max(version::text) FROM supabase_migrations.schema_migrations),'functions',(SELECT jsonb_agg(to_jsonb(f)) FROM (${ports.join(' UNION ALL ')}) f),'backend1165594',${backend}) AS current_metadata`;
 const ref=environment==="PROD"?"YOUR_PROJECT_REF":"YOUR_PROJECT_REF";
 const response=await fetch(`https://api.supabase.com/v1/projects/${ref}/database/query`,{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({query,read_only:true}),signal:AbortSignal.timeout(20000)});
 const at=new Date().toISOString();if(!response.ok)return{environment,at,http:response.status,status:"READONLY-METADATA-UNAVAILABLE"};const data=await response.json();return{environment,at,http:response.status,read_only:true,query,current:data[0]?.current_metadata};
}));
const file=path.join(own,`PT409-CURRENT-METADATA-${new Date().toISOString().replaceAll(/[:.]/gu,"-")}.json`);const content=JSON.stringify({at:new Date().toISOString(),results},null,2);await writeFile(file,content,{flag:"wx"});console.log(JSON.stringify({evidence:file,evidence_sha256:sha(content),results:results.map(({environment,http,current,status})=>({environment,http,current,status}))}));
